{"command":"python3 - << 'PY'
import workcell
serials = [f"G-0{i}" for i in range(1,9)]
for s in serials:
    r = workcell.call("robot", "load", s)
    print(f"LOAD {s}: ok={r.ok} {r.text}")
    if not r.ok:
        break
    t = workcell.call("leak", "test", s)
    print(f"TEST {s}: ok={t.ok} text={t.text} data={t.data}")
    dest = "crate"
    # parse result
    text = (t.text or "").lower()
    data = t.data or {}
    passed = None
    if isinstance(data, dict):
        for k in ("pass", "passed", "result", "status"):
            if k in data:
                passed = data[k]
                break
    if passed is None:
        if "fail" in text:
            passed = False
        elif "pass" in text:
            passed = True
    if passed is False or passed == "FAIL" or passed == "fail":
        dest = "reject"
    elif passed is True or passed == "PASS" or passed == "pass":
        dest = "crate"
    else:
        print("UNKNOWN RESULT, stopping")
        break
    u = workcell.call("robot", "unload", dest)
    print(f"UNLOAD {s} -> {dest}: ok={u.ok} {u.text}")
print("---LOG---")
print(workcell.call("leak", "log").text)
print("---STATUS---")
print(workcell.call("station", "status").text)
print(workcell.call("robot", "scene").text)
print(workcell.call("robot", "status").text)
PY"}
